using System;using System.IO;using System.Collections.Generic;
class BusyFixtures {
static void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("PASS "+label);}
static void Main(){string folder=Path.GetFullPath("dev/2026-10-25-busy-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"node.exe"),"fixture");Check(!SceneBlockProcessUsage.IsBusy(folder,new[]{Path.Combine(folder+"-other","node.exe")},p=>false),"unrelated runtime does not block");Check(SceneBlockProcessUsage.IsBusy(folder,new[]{Path.Combine(folder,"node.exe")},p=>false),"exact installation process blocks");Check(!SceneBlockProcessUsage.IsBusy(folder,new string[0],p=>false),"unknown external process is not fabricated as owned");Check(SceneBlockProcessUsage.IsBusy(folder,new string[0],p=>p.EndsWith("node.exe")),"owned executable lock blocks without process metadata");Check(SceneBlockProcessUsage.IsBusy(folder,new string[0],p=>{throw new UnauthorizedAccessException();}),"own file inspection failure blocks");Check(!SceneBlockProcessUsage.IsBusy(folder,new[]{Path.Combine(folder,"node.exe")},p=>false,Path.Combine(folder,"node.exe")),"self management process excluded");}
}
